import{_ as t}from"./chunks/string_job.D9CE2ynq.js";import{_ as e,o,c as l,a0 as i}from"./chunks/framework.akKRIpjQ.js";const q=JSON.parse('{"title":"04 · 穿线记录","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/04-stringing-log.md","filePath":"zh/guide/04-stringing-log.md"}'),n={name:"zh/guide/04-stringing-log.md"};function d(r,a,s,p,c,h){return o(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="_04-·-穿线记录" tabindex="-1">04 · 穿线记录 <a class="header-anchor" href="#_04-·-穿线记录" aria-label="Permalink to &quot;04 · 穿线记录&quot;">​</a></h1><blockquote><p>4 个功能中的第 3 个。每次穿线写一条 + 到点提醒。</p></blockquote><h2 id="它能做什么" tabindex="-1">它能做什么 <a class="header-anchor" href="#它能做什么" aria-label="Permalink to &quot;它能做什么&quot;">​</a></h2><img src="'+t+`" alt="添加一条穿线记录" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>每支球拍 <a href="./03-racquets.html#详情页">详情页</a> 上的&quot;穿线记录&quot;Tab。每条记录是一次穿线：</p><ul><li>日期</li><li>线材（主 / 横）</li><li>磅数（主 / 横）</li><li>穿线师（选填）</li><li>备注</li><li><strong>来源</strong> ——「手动」/「来自 <a href="./05-tension-conversion.html">05 · 张力换算</a>」（如果是张力换算跳转来的）</li></ul><p>最新一条的日期同时驱动该球拍列表页上的&quot;上次穿线&quot;戳记。</p><h2 id="录一次穿线" tabindex="-1">录一次穿线 <a class="header-anchor" href="#录一次穿线" aria-label="Permalink to &quot;录一次穿线&quot;">​</a></h2><p>进入某支球拍详情 → <code>穿线记录</code> Tab：</p><ol><li><code>+ 添加穿线记录</code></li><li>录入：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>日期</td><td>今天</td><td>过去的日期也行</td></tr><tr><td>线材主</td><td>空</td><td>下拉（预置线材库：Yonex BG65 / BG80、Wilson NXT、聚酯系列等）；可自填</td></tr><tr><td>线材横</td><td>空</td><td>选填；单线打法留空</td></tr><tr><td>主磅数</td><td>沿用球拍档案</td><td>lbs 或 kg；可临时覆盖</td></tr><tr><td>横磅数</td><td>沿用</td><td>选填</td></tr><tr><td>穿线师</td><td>空</td><td>自由文本</td></tr><tr><td>备注</td><td>空</td><td>&quot;手胶 2 层 / 减震 1 个 / 拉了 30 分钟&quot;</td></tr><tr><td>来源</td><td>手动</td><td>若通过 <a href="./05-tension-conversion.html">第 5 章</a> 跳入，自动标为「来自张力换算」</td></tr></tbody></table><ol start="3"><li><code>保存</code></li></ol><blockquote><p><strong>不知道线材型号？</strong> 进穿线日志 → <code>线材库</code> 看我们预置的几百款；找不到可自填。</p></blockquote><h2 id="线材库" tabindex="-1">线材库 <a class="header-anchor" href="#线材库" aria-label="Permalink to &quot;线材库&quot;">​</a></h2><p>下拉背后是一个离线数据库：</p><ul><li>品牌：Yonex、Wilson、Babolat、Head、Prince、Luxilon、Tecnifibre…</li><li>类型：多股尼龙 / 聚酯 / 肠线 / 混合</li><li>每条：典型打球寿命（小时）、推荐磅数区间</li></ul><blockquote><p>按类型筛选可以只看&quot;你真用过的&quot;。</p></blockquote><h2 id="换线提醒" tabindex="-1">换线提醒 <a class="header-anchor" href="#换线提醒" aria-label="Permalink to &quot;换线提醒&quot;">​</a></h2><h3 id="方式-a-·-按时间" tabindex="-1">方式 A · 按时间 <a class="header-anchor" href="#方式-a-·-按时间" aria-label="Permalink to &quot;方式 A · 按时间&quot;">​</a></h3><p>最简单的：每个 N 天提醒一次。</p><ul><li>设定 N（默认 90，可选 30 / 60 / 90 / 120 / 180）</li><li>提醒时间窗（默认 <code>09:00</code>，可改）</li><li>触发后会自动归档&quot;上次穿线&quot;日期，下次提醒从那一天起算</li></ul><h3 id="方式-b-·-按打球小时数" tabindex="-1">方式 B · 按打球小时数 <a class="header-anchor" href="#方式-b-·-按打球小时数" aria-label="Permalink to &quot;方式 B · 按打球小时数&quot;">​</a></h3><p>更精细：估算你每周打球 × 时长 → 折算到总打球小时，达到目标数（比如 80 小时）就提醒。</p><ul><li>每周打球频率（次）</li><li>每次平均时长（小时）</li><li>目标打球小时数（默认 80 小时 / 线；横线建议 60 小时）</li><li><strong>线材类型系数</strong>（多股尼龙 1.0；聚酯线 0.7；肠线 0.5）—— 聚酯比尼龙更不耐磨，所以系数更低</li></ul><blockquote><p>例：每周 3 次 × 2 小时 = 6 小时/周，尼龙 1.0 → 80 / 6 ≈ 13 周 ≈ 3 个月。</p></blockquote><p>App 内有&quot;竖线、横线分别提醒&quot;开关（方式 B 适用）。</p><h2 id="提醒长什么样" tabindex="-1">提醒长什么样? <a class="header-anchor" href="#提醒长什么样" aria-label="Permalink to &quot;提醒长什么样?&quot;">​</a></h2><p>Android 系统通知：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────┐</span></span>
<span class="line"><span>│ 🏸 AceCrush Craft        9:00 AM    │</span></span>
<span class="line"><span>│                                      │</span></span>
<span class="line"><span>│ &quot;主力 Blade&quot; 该换线了                │</span></span>
<span class="line"><span>│ 上次穿线：2026-04-15，已过 92 天     │</span></span>
<span class="line"><span>│                                      │</span></span>
<span class="line"><span>│ [稍后提醒] [查看] [标记已换]            │</span></span>
<span class="line"><span>└──────────────────────────────────────┘</span></span></code></pre></div><ul><li><code>标记已换</code> → 自动跳到「添加穿线记录」页（填日期就行，旧记录归档）</li><li><code>稍后提醒</code> → 推后 24 小时</li><li><code>查看</code> → 跳到该球拍详情页</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="磅数可以从张力换算里直接带过来吗" tabindex="-1">磅数可以从张力换算里直接带过来吗? <a class="header-anchor" href="#磅数可以从张力换算里直接带过来吗" aria-label="Permalink to &quot;磅数可以从张力换算里直接带过来吗?&quot;">​</a></h3><p>可以！这正是 <a href="./05-tension-conversion.html">05 · 张力换算</a> 的设计。在张力换算结果页，点 <strong>「用此张力记录穿线」</strong>，App 会直接跳进「添加穿线记录」表单 —— 磅数预填、球拍预选、来源标为「来自张力换算」。</p><h3 id="提醒被系统关掉怎么办" tabindex="-1">提醒被系统关掉怎么办? <a class="header-anchor" href="#提醒被系统关掉怎么办" aria-label="Permalink to &quot;提醒被系统关掉怎么办?&quot;">​</a></h3><p>进系统 <code>设置 → 应用 → AceCrush Craft → 通知</code>，把&quot;允许通知&quot;开回来。 进 App 「我的」Tab → <code>通知与提醒</code>，把所有开关重置。</p><h3 id="线材库在哪" tabindex="-1">线材库在哪? <a class="header-anchor" href="#线材库在哪" aria-label="Permalink to &quot;线材库在哪?&quot;">​</a></h3><p>App 内离线，App 升级时同步更新；你也可以自填型号。</p><h3 id="同一支拍一个月穿了两次-都要录吗" tabindex="-1">同一支拍一个月穿了两次，都要录吗? <a class="header-anchor" href="#同一支拍一个月穿了两次-都要录吗" aria-label="Permalink to &quot;同一支拍一个月穿了两次，都要录吗?&quot;">​</a></h3><p>每次穿线一条独立记录。提醒默认基于&quot;最新一次&quot;。</p><h2 id="删除一支球拍" tabindex="-1">删除一支球拍? <a class="header-anchor" href="#删除一支球拍" aria-label="Permalink to &quot;删除一支球拍?&quot;">​</a></h2><p>进入详情页 → 右上角 <code>···</code> → <code>删除球拍</code>。</p><blockquote><p>删除时<strong>所有穿线记录会一起删除</strong>（无悬空数据）。再提醒一次：这些数据<strong>只在本机</strong>，没有云备份——请提前到 <code>设置 → 导出 → JSON</code> 备份。</p></blockquote>`,42)])])}const g=e(n,[["render",d]]);export{q as __pageData,g as default};
